import { useState, type ReactNode } from 'react'
import type { CrmCollaborator, CrmEvent } from '../types/domain'
import type { Activity, ActivityTemplate, EquipmentAsset, JournalEntry, Logistics, ProductionContext, ProductionPlan } from './model'
import { balance, contractServices, costTotal, durationMinutes, operationalUtility } from './rules'
import { collaboratorMessage, exportProductionPdf, productionDate, whatsappLink } from './exports'
import { mergeOfferPlan, suggestResources } from './autoplan'
import { contractUrl } from './contractDocument'
import { simpleChecklist } from './simpleWorkflow'
import { applyActivityTemplates, mergeReturnChecklist, parseActivityTemplates, returnChecklist, templateProblems } from './advancedTemplates'
import './advanced.css'

interface AdvancedProductionProps {
  event: CrmEvent
  plan: ProductionPlan
  onChange: (plan: ProductionPlan) => void
  collaborators: CrmCollaborator[]
  assets: EquipmentAsset[]
  contexts: ProductionContext[]
  onCreateAsset: (input: Omit<EquipmentAsset, 'id'>) => Promise<EquipmentAsset | void>
  onUpdateAsset?: (assetId: string, patch: Partial<Omit<EquipmentAsset, 'id'>>) => Promise<EquipmentAsset | void>
  journal: JournalEntry[]
  userId: string
}
const sections = ['Resumen avanzado', 'Contrato y servicios', 'Cronograma detallado', 'Personal detallado', 'Inventario', 'Logística', 'Salida y retorno', 'Costos y utilidad', 'Historial', 'Plantillas']
const roleNames = ['DJ', 'Animador', 'Animadora', 'Maquilladora', 'Responsable de Glitter', 'Personal de instalación', 'Asistente de producción', 'Conductor', 'Responsable de desmontaje', 'Supervisor general']
const activityStatus: Record<Activity['status'], string> = { pending: 'Pendiente', preparing: 'En preparación', live: 'En curso', completed: 'Completado', cancelled: 'Cancelado' }
const activityKind: Record<Activity['kind'], string> = { setup: 'Instalación', test: 'Pruebas', show: 'Actuación / servicio', travel: 'Traslado', teardown: 'Desmontaje', other: 'Otra actividad' }
const equipmentStatus = { reserved: 'Reservado', installed: 'Instalado', in_use: 'En uso', pickup: 'Pendiente de recojo', available: 'Disponible', maintenance: 'En mantenimiento' }
const stageNames = { before: 'Antes del evento', setup: 'Durante la instalación', show: 'Durante el show', after: 'Después del evento' }
const commonActivities: { name: string; kind: Activity['kind'] }[] = [
  { name: 'Salida del almacén', kind: 'travel' }, { name: 'Llegada al local', kind: 'travel' }, { name: 'Descarga', kind: 'setup' }, { name: 'Instalación', kind: 'setup' },
  { name: 'Pruebas técnicas', kind: 'test' }, { name: 'Recepción de invitados', kind: 'show' }, { name: 'DJ previo', kind: 'show' }, { name: 'Estación Glitter', kind: 'show' },
  { name: 'Inicio de animación', kind: 'show' }, { name: 'Juegos y dinámicas', kind: 'show' }, { name: 'Just Dance o Karaoke', kind: 'show' }, { name: 'Mini Hora Loca', kind: 'show' },
  { name: 'DJ de cierre', kind: 'show' }, { name: 'Finalización', kind: 'other' }, { name: 'Desmontaje', kind: 'teardown' }, { name: 'Recojo y retorno', kind: 'travel' },
]
const id = () => crypto.randomUUID()
const amount = (value: number) => `S/ ${Number(value || 0).toFixed(2)}`
function replaceRow<T extends { id: string }>(rows: T[], rowId: string, change: Partial<T>): T[] { return rows.map(row => row.id === rowId ? { ...row, ...change } : row) }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="prod-field"><span>{label}</span>{children}</label> }
function People({ label, selected, people, onChange }: { label: string; selected: string[]; people: CrmCollaborator[]; onChange: (ids: string[]) => void }) {
  return <fieldset className="prod-people"><legend>{label}</legend><div className="prod-checks">{people.length ? people.map(person => <label key={person.id}><input type="checkbox" checked={selected.includes(person.id)} onChange={e => onChange(e.target.checked ? [...selected, person.id] : selected.filter(value => value !== person.id))} />{person.nombre}</label>) : <p className="prod-empty">Agrega colaboradores en el CRM.</p>}</div></fieldset>
}
export function AdvancedProduction({ event, plan, onChange, collaborators, assets, contexts, onCreateAsset, onUpdateAsset, journal, userId }: AdvancedProductionProps) {
  const [section, setSection] = useState(4)
  const [preset, setPreset] = useState('')
  const [selectedPerson, setSelectedPerson] = useState('')
  const [selectedAsset, setSelectedAsset] = useState('')
  const [newTask, setNewTask] = useState('')
  const [newTaskStage, setNewTaskStage] = useState<keyof typeof stageNames>('before')
  const [agreement, setAgreement] = useState('')
  const [agreementResponsible, setAgreementResponsible] = useState('')
  const [agreementDate, setAgreementDate] = useState('')
  const [assetName, setAssetName] = useState('')
  const [assetIdentifier, setAssetIdentifier] = useState('')
  const [assetCategory, setAssetCategory] = useState('Sonido')
  const [assetBusy, setAssetBusy] = useState(false)
  const [localMessage, setLocalMessage] = useState('')
  const [incident, setIncident] = useState('')
  const [incidentKind, setIncidentKind] = useState('Incidencia')
  const [editingAsset, setEditingAsset] = useState<EquipmentAsset | null>(null)
  const set = <K extends keyof ProductionPlan>(key: K, value: ProductionPlan[K]) => onChange({ ...plan, [key]: value })
  const logistics = <K extends keyof Logistics>(key: K, value: Logistics[K]) => set('logistics', { ...plan.logistics, [key]: value })
  const services = contractServices(event)
  const pdf = contractUrl(event.drive_pdf_url)
  const assignedPeople = collaborators.filter(person => plan.staff.some(item => item.collaboratorId === person.id))
  const additionalPayments = plan.payments.reduce((sum, payment) => sum + Number(payment.amount || 0), 0)
  const staffingCosts = plan.staff.reduce((sum, person) => sum + Number(person.fee || 0), 0)
  const operatingCosts = costTotal(plan)
  const departure = simpleChecklist(event, plan)
  const returns = returnChecklist(event, plan)
  const templates = plan.activityTemplates || []
  const updateTemplate = (template: ActivityTemplate, patch: Partial<ActivityTemplate>) => set('activityTemplates', templates.map(item => item.id === template.id ? { ...item, ...patch } : item))
  const addActivity = () => {
    const choice = commonActivities.find(item => item.name === preset)
    set('activities', [...plan.activities, { id: id(), name: choice?.name || 'Nueva actividad', start: '', end: '', responsibleIds: [], notes: '', status: 'pending', kind: choice?.kind || 'other', confirmed: false }])
    setPreset('')
  }
  const downloadOriginal = async () => {
    if (!pdf) return
    try {
      const response = await fetch(pdf.original, { credentials: 'omit', referrerPolicy: 'no-referrer' })
      if (!response.ok) throw new Error('No disponible')
      const blob = await response.blob()
      if (!blob.type.includes('pdf')) throw new Error('El proveedor no entregó un PDF directo')
      const objectUrl = URL.createObjectURL(blob)
      const anchor = document.createElement('a'); anchor.href = objectUrl; anchor.download = `contrato_original_${event.fecha_evento}.pdf`; anchor.click()
      window.setTimeout(() => URL.revokeObjectURL(objectUrl), 10000)
    } catch { setLocalMessage('El proveedor no permite la descarga directa. Abre el original y usa su opción Descargar; puede requerir iniciar sesión.') }
  }
  const safeExport = (staffOnly: boolean, collaboratorId?: string) => { try { exportProductionPdf([{ event, plan }], collaborators, assets, staffOnly, collaboratorId) } catch { setLocalMessage('No se pudo generar el PDF. Revisa los datos e inténtalo nuevamente.') } }
  return <div className="prod-organizer prod-advanced">
    <div className="prod-advanced-intro"><span className="eyebrow">HERRAMIENTAS AVANZADAS</span><p>Inventario, costos, logística y configuración interna del evento. Los cambios del plan se guardan con Guardar producción.</p></div>
    <nav className="prod-tabs" aria-label="Secciones avanzadas de producción">{sections.map((name, index) => <button key={name} className={section === index ? 'active' : undefined} type="button" aria-current={section === index ? 'page' : undefined} onClick={() => { setSection(index); setLocalMessage('') }}>{index + 1}. {name}</button>)}</nav>
    <div className="prod-actions"><button type="button" onClick={() => { const result = mergeOfferPlan(event, plan); onChange(result.plan); setLocalMessage(`Borrador actualizado: ${result.addedActivities} actividades, ${result.addedChecklist} tareas y ${result.addedCommitments} compromisos nuevos. Se conservaron ${result.preservedActivities} actividades existentes sin sobrescribir sus horarios ni responsables. Revisa el resultado y guarda la producción.`) }}>Actualizar borrador desde contrato</button><small>Añade solo novedades del cronograma y los servicios registrados. Conserva las ediciones, asignaciones y confirmaciones existentes.</small></div>
    <div className="prod-actions"><button type="button" onClick={() => { const result = suggestResources(event, plan, collaborators, assets, contexts); onChange(result.plan); setLocalMessage(`Sugerencia en borrador: ${result.staffAdded} funciones pendientes de confirmación, ${result.equipmentAdded} reservas de equipos y ${result.responsibilitiesAdded} actividades con responsable compatible. Revisa y guarda los cambios.\n${result.warnings.join('\n')}`) }}>Sugerir recursos disponibles</button><small>Usa funciones reales y horarios completos. Excluye cruces, traslados insuficientes y mantenimiento. Las propuestas requieren tu revisión y confirmación.</small></div>
    {localMessage && <p className="prod-note" role="status">{localMessage}</p>}
    <section className="prod-section" aria-label={sections[section]}>
      <div className="prod-section-heading"><h2>{sections[section]}</h2><span className="prod-muted">Los cambios se guardan con el botón Guardar producción.</span></div>

      {section === 0 && <>
        <dl className="prod-summary"><div><dt>Cliente</dt><dd>{event.cliente}</dd></div><div><dt>Protagonista</dt><dd>{event.agasajado || 'No registrado'}</dd></div><div><dt>Fecha</dt><dd>{productionDate(event.fecha_evento)}</dd></div><div><dt>Horario contractual</dt><dd>{event.hora_inicio} – {event.hora_fin || 'Por confirmar'}</dd></div><div><dt>Dirección</dt><dd>{event.direccion || 'Por confirmar'}</dd></div><div><dt>Distrito</dt><dd>{event.lugar || 'Por confirmar'}</dd></div><div><dt>Paquete</dt><dd>{event.paquete}</dd></div><div><dt>Invitados</dt><dd>{event.invitados ?? 'No registrado'}</dd></div><div><dt>Teléfono del cliente</dt><dd>{event.telefono || 'No registrado'}</dd></div><div><dt>Reserva / pago del contrato</dt><dd>{event.estado_pago}</dd></div></dl>
        {event.observaciones && <div className="prod-note"><b>Observaciones importantes del CRM</b><p className="prod-preserve">{event.observaciones}</p></div>}
        <div className="prod-metrics"><div className="prod-metric"><span>Actividades</span><strong>{plan.activities.length}</strong></div><div className="prod-metric"><span>Colaboradores</span><strong>{assignedPeople.length}</strong></div><div className="prod-metric"><span>Equipos</span><strong>{plan.equipment.length}</strong></div><div className="prod-metric"><span>Checklist completado</span><strong>{plan.checklist.filter(item => item.done).length}/{plan.checklist.length}</strong></div></div>
        <p className="prod-note">El contrato es la referencia comercial. Este organizador mantiene la planificación y los acuerdos adicionales por separado. Las advertencias y la validación para «Listo para ejecución» aparecen en la cabecera.</p>
        <Field label="Notas internas de producción"><textarea rows={5} value={plan.notes} onChange={e => set('notes', e.target.value)} placeholder="Información interna para la coordinación del evento." /></Field>
        <div className="prod-actions"><button type="button" onClick={() => safeExport(false)}>Descargar PDF operativo</button><button type="button" onClick={() => safeExport(true)}>Hoja de trabajo del equipo</button></div>
      </>}

      {section === 1 && <>
        <p className="prod-note">Los campos siguientes provienen del evento existente y son de solo lectura en producción. La fecha de creación de la reserva no acredita la fecha de emisión del PDF.</p>
        {pdf ? <><div className="prod-actions"><a href={pdf.original} target="_blank" rel="noopener noreferrer">Abrir contrato original en otra pestaña</a><button type="button" onClick={() => void downloadOriginal()}>Descargar PDF original</button></div><p className="prod-muted">Versión y fecha de generación: no registradas por el CRM actual. El proveedor puede solicitar acceso o impedir la vista integrada.</p><iframe className="prod-contract-frame" title="Contrato original enlazado en el CRM" src={pdf.preview} referrerPolicy="no-referrer" sandbox="allow-scripts allow-same-origin allow-popups allow-downloads" /></> : <><p className="prod-warning" role="status">{event.drive_pdf_url ? 'El enlace registrado no es una URL HTTPS válida; no se abrirá. Revisa el archivo desde el CRM.' : 'Este evento no tiene PDF original enlazado. Se muestran los datos contractuales disponibles; no se ha creado ni reconstruido un contrato.'}</p><p className="prod-muted">Fecha de generación y versión del contrato: no disponibles en los campos existentes.</p></>}
        <dl className="prod-contract-data"><dt>Paquete</dt><dd>{event.paquete}</dd><dt>Documento del contratante registrado</dt><dd>{event.dni_ruc || event.dni || 'No registrado'}</dd><dt>Detalle exacto del servicio</dt><dd className="prod-preserve">{event.detalle_servicio || 'No registrado'}</dd><dt>Juegos y dinámicas</dt><dd className="prod-preserve">{event.juegos_elegidos || 'No registrados'}</dd><dt>Cronograma contractual original</dt><dd className="prod-preserve">{event.cronograma || 'No registrado'}</dd><dt>Adicionales y requerimientos registrados</dt><dd className="prod-preserve">{event.adicionales_requerimientos || 'No registrados'}</dd>{event.adicionales?.trim() && <><dt>Adicionales del campo histórico del CRM</dt><dd className="prod-preserve">{event.adicionales}</dd></>}{event.movilidad?.trim() && <><dt>Movilidad registrada en el CRM</dt><dd className="prod-preserve">{event.movilidad} · Verificar frente al detalle contractual.</dd></>}</dl>
        <h3>Contratado frente a preparado</h3><p className="prod-muted">«No consta» significa que el texto no confirma ese servicio. Revisa las condiciones, exclusiones y alternativas en la evidencia contractual; no se deducen inclusiones a partir del nombre del paquete.</p>
        <div className="prod-table-wrap"><table className="prod-table"><thead><tr><th>Servicio / evidencia contractual</th><th>Contratado</th><th>Planificado</th><th>Preparado</th><th>Confirmado con cliente</th><th>Ejecutado</th><th>Estado</th></tr></thead><tbody>{services.map(service => {
          const commitment = plan.commitments.find(item => item.key === service.key) || { key: service.key, planned: false, prepared: false, clientConfirmed: false, executed: false, notes: '' }
          const change = (patch: Partial<typeof commitment>) => set('commitments', [...plan.commitments.filter(item => item.key !== service.key), { ...commitment, ...patch }])
          return <tr key={service.key}><th scope="row" style={{ minWidth: 250, whiteSpace: 'normal' }}>{service.label}{service.durationMinutes !== undefined && <small>{service.durationMinutes} min contractuales</small>}<details><summary>Ver evidencia</summary><p className="prod-preserve">{service.evidence || 'No se encontró una afirmación expresa en los campos existentes.'}</p></details><input aria-label={`Nota de planificación: ${service.label}`} placeholder="Nota interna del compromiso" value={commitment.notes} onChange={e => change({ notes: e.target.value })} /></th><td>{service.contracted === true ? 'Sí' : service.contracted === false ? 'Excluido' : 'No consta'}</td>{(['planned', 'prepared', 'clientConfirmed', 'executed'] as const).map(key => <td key={key}><input aria-label={`${service.label}: ${key === 'planned' ? 'planificado' : key === 'prepared' ? 'preparado' : key === 'clientConfirmed' ? 'confirmado con cliente' : 'ejecutado'}`} type="checkbox" checked={commitment[key]} onChange={e => change({ [key]: e.target.checked })} /></td>)}<td><span className={service.contracted && !commitment.prepared ? 'prod-risk' : commitment.prepared ? 'prod-ready' : 'prod-muted'}>{service.contracted && !commitment.prepared ? 'Pendiente' : commitment.prepared ? 'Preparado' : 'Por revisar'}</span></td></tr>
        })}</tbody></table></div>
        <label className="prod-check"><input type="checkbox" checked={plan.reviewedContract} onChange={e => set('reviewedContract', e.target.checked)} /> Revisé el contrato, los servicios, las exclusiones y las condiciones particulares.</label>
        <h3>Acuerdos y modificaciones confirmados con el cliente</h3><p>Registra la coordinación, su fecha y el responsable. No modifica el contrato original. Los acuerdos guardados quedan en el historial.</p>
        <div className="prod-grid"><Field label="Fecha y hora del acuerdo (Lima)"><input type="datetime-local" value={agreementDate} onChange={e => setAgreementDate(e.target.value)} /></Field><Field label="Responsable del acuerdo"><input value={agreementResponsible} onChange={e => setAgreementResponsible(e.target.value)} placeholder="Nombre del responsable" /></Field><Field label="Acuerdo confirmado / referencia de adenda"><textarea value={agreement} onChange={e => setAgreement(e.target.value)} placeholder="Detalle exacto y referencia al soporte del acuerdo, si existe." /></Field></div>
        <button type="button" disabled={!agreement.trim() || !agreementResponsible.trim() || !agreementDate} onClick={() => { set('agreements', [...plan.agreements, { id: id(), date: agreementDate, responsible: agreementResponsible.trim(), note: agreement.trim() }]); setAgreement(''); setAgreementDate('') }}>Registrar acuerdo en el borrador</button>
        <div className="prod-journal">{plan.agreements.map(item => <article key={item.id}><b>{productionDate(item.date)} · {item.responsible}</b><p className="prod-preserve">{item.note}</p></article>)}</div>
      </>}

      {section === 2 && <>
        <p className="prod-note">Editor interno opcional con fechas y horas completas de Lima. Las actividades nuevas quedan como propuestas hasta que las confirmes. Puedes guardar un borrador incompleto sin alterar el contrato.</p>
        <p className="prod-note">El borrador importa únicamente horarios que se pueden interpretar del cronograma contractual. Los horarios aproximados o ambiguos requieren revisión. Una hora puntual de instalación no define su duración; las actividades y los responsables pendientes siguen sin confirmar.</p>
        {event.cronograma && <details className="prod-note"><summary>Consultar cronograma contractual de referencia</summary><p className="prod-preserve">{event.cronograma}</p></details>}
        <div className="prod-actions"><Field label="Actividad habitual"><select value={preset} onChange={e => setPreset(e.target.value)}><option value="">Actividad personalizada</option>{commonActivities.map(item => <option key={item.name}>{item.name}</option>)}</select></Field><button type="button" onClick={addActivity}>Añadir actividad</button></div>
        <Timeline activities={plan.activities} />
        {!plan.activities.length && <p className="prod-empty">Añade las actividades del evento. No se han inventado horarios ni responsables.</p>}
        <div className="prod-resource-list">{plan.activities.map((activity, index) => {
          const update = (patch: Partial<Activity>) => { const contentChanged = ['name', 'start', 'end', 'kind', 'serviceKey', 'responsibleIds'].some(key => key in patch); set('activities', replaceRow(plan.activities, activity.id, { ...patch, ...(contentChanged ? { confirmed: false, confirmedAt: undefined } : {}) })) }
          const duration = durationMinutes(activity.start, activity.end)
          return <article className="prod-resource-card" key={activity.id}><div className="prod-row-heading"><h3>{index + 1}. {activity.name || 'Actividad sin nombre'}</h3><button type="button" className="prod-danger" aria-label={`Quitar actividad ${activity.name}`} onClick={() => set('activities', plan.activities.filter(item => item.id !== activity.id))}>Quitar</button></div><div className="prod-grid"><Field label="Nombre de la actividad"><input value={activity.name} onChange={e => update({ name: e.target.value })} /></Field><Field label="Tipo de actividad"><select value={activity.kind} onChange={e => update({ kind: e.target.value as Activity['kind'] })}>{Object.entries(activityKind).map(([value, name]) => <option value={value} key={value}>{name}</option>)}</select></Field><Field label="Inicio (Lima)"><input type="datetime-local" value={activity.start} onChange={e => update({ start: e.target.value })} /></Field><Field label="Fin (Lima)"><input type="datetime-local" value={activity.end} onChange={e => update({ end: e.target.value })} /></Field><Field label="Estado de actividad"><select value={activity.status} onChange={e => update({ status: e.target.value as Activity['status'] })}>{Object.entries(activityStatus).map(([value, name]) => <option value={value} key={value}>{name}</option>)}</select></Field><Field label="Servicio contractual relacionado"><select value={activity.serviceKey || ''} onChange={e => update({ serviceKey: e.target.value || undefined })}><option value="">Sin vínculo / logística</option>{services.filter(item => item.contracted === true).map(item => <option key={item.key} value={item.key}>{item.label}</option>)}</select></Field></div><label className="prod-check"><input type="checkbox" checked={activity.confirmed === true} disabled={!activity.name.trim() || !activity.start || !activity.end || duration <= 0} onChange={e => update({ confirmed: e.target.checked, confirmedAt: e.target.checked ? new Date().toISOString() : undefined })} /><span>Actividad confirmada para ejecución{activity.confirmedAt && <small>Confirmada {productionDate(activity.confirmedAt)}</small>}</span></label><p className="prod-duration">Duración calculada: {Number.isFinite(duration) && duration > 0 ? `${duration} minutos` : 'Completa un rango válido'}</p><People label="Responsables de esta actividad" people={assignedPeople} selected={activity.responsibleIds} onChange={responsibleIds => update({ responsibleIds })} /><div className="prod-grid"><Field label="Observaciones internas de actividad"><textarea value={activity.notes} onChange={e => update({ notes: e.target.value })} /></Field><Field label="Justificación de excepción de horario o simultaneidad"><textarea value={activity.exception || ''} onChange={e => update({ exception: e.target.value })} placeholder="Explica la coordinación válida. La justificación queda registrada al guardar." /></Field></div></article>
        })}</div>
      </>}

      {section === 3 && <>
        <div className="prod-actions"><Field label="Colaborador del CRM"><select value={selectedPerson} onChange={e => setSelectedPerson(e.target.value)}><option value="">Selecciona una persona</option>{collaborators.filter(person => person.activo).map(person => <option key={person.id} value={person.id}>{person.nombre} · {person.rol}</option>)}</select></Field><button type="button" disabled={!selectedPerson} onClick={() => { set('staff', [...plan.staff, { id: id(), collaboratorId: selectedPerson, role: '', arrival: '', start: '', end: '', confirmation: 'pending', notes: '', fee: 0, transferMinutes: 0 }]); setSelectedPerson('') }}>Añadir función</button></div>
        <p className="prod-muted">Puedes añadir varias funciones a una persona. La llegada y salida delimitan su compromiso; completa el margen de traslado. Una nueva función queda pendiente de confirmación.</p>
        <div className="prod-resource-list">{plan.staff.map(assignment => {
          const person = collaborators.find(item => item.id === assignment.collaboratorId)
          const update = (patch: Partial<typeof assignment>) => set('staff', replaceRow(plan.staff, assignment.id, patch))
          const commitmentsElsewhere = contexts.filter(context => context.event.id !== event.id).flatMap(context => context.plan.staff.filter(item => item.collaboratorId === assignment.collaboratorId).map(item => ({ event: context.event, assignment: item })))
          const whatsapp = person ? whatsappLink(person, collaboratorMessage(event, plan, person)) : null
          return <article className="prod-resource-card" key={assignment.id}><div className="prod-row-heading"><div><h3>{person?.nombre || 'Colaborador no disponible'}</h3><p>{person?.telefono || 'Sin teléfono registrado'}</p></div><button type="button" className="prod-danger" onClick={() => set('staff', plan.staff.filter(item => item.id !== assignment.id))}>Quitar función</button></div><div className="prod-grid"><Field label="Función específica"><input value={assignment.role} list="production-roles" onChange={e => update({ role: e.target.value })} placeholder="Elige o escribe una función" /></Field><Field label="Estado de confirmación"><select value={assignment.confirmation} onChange={e => update({ confirmation: e.target.value as typeof assignment.confirmation })}><option value="pending">Pendiente</option><option value="confirmed">Confirmado</option><option value="declined">No disponible / rechazado</option></select></Field><Field label="Llegada (Lima)"><input type="datetime-local" value={assignment.arrival} onChange={e => update({ arrival: e.target.value })} /></Field><Field label="Inicio de función (Lima)"><input type="datetime-local" value={assignment.start} onChange={e => update({ start: e.target.value })} /></Field><Field label="Salida (Lima)"><input type="datetime-local" value={assignment.end} onChange={e => update({ end: e.target.value })} /></Field><Field label="Traslado necesario después (minutos)"><input type="number" min="0" value={assignment.transferMinutes} onChange={e => update({ transferMinutes: Math.max(0, Number(e.target.value)) })} /></Field><Field label="Honorarios de esta función (S/)"><input type="number" min="0" step="0.01" value={assignment.fee} onChange={e => update({ fee: Math.max(0, Number(e.target.value)) })} /></Field><Field label="Observaciones internas de función"><textarea value={assignment.notes} onChange={e => update({ notes: e.target.value })} /></Field></div>{commitmentsElsewhere.length > 0 && <details className="prod-note"><summary>Compromisos de esta persona en otros eventos ({commitmentsElsewhere.length})</summary>{commitmentsElsewhere.map(({ event: other, assignment: item }) => <p key={`${other.id}-${item.id}`}>{other.agasajado || other.cliente} · {other.lugar} · {item.role} · {productionDate(item.arrival || item.start)} – {productionDate(item.end)}</p>)}</details>}<div className="prod-actions">{whatsapp && <a href={whatsapp} target="_blank" rel="noopener noreferrer">Preparar WhatsApp para {person?.nombre}</a>}<button type="button" onClick={() => safeExport(true, assignment.collaboratorId)}>Hoja de trabajo individual</button></div></article>
        })}</div><datalist id="production-roles">{roleNames.map(role => <option key={role} value={role} />)}</datalist>
        {!plan.staff.length && <p className="prod-empty">El equipo sigue pendiente. Selecciona un colaborador existente para asignarle una función.</p>}
        <p className="prod-note">WhatsApp abre un mensaje preparado para revisión. Debes confirmar el envío en WhatsApp. Los mensajes y las hojas de trabajo no incluyen honorarios, utilidad ni notas internas.</p>
      </>}

      {section === 4 && <>
        <h3>Inventario general registrado</h3><p className="prod-muted">El estado del inventario indica si un equipo está operativo o en mantenimiento. Sus reservas se consultan por evento; no se cambian automáticamente al abrir esta pantalla.</p>
        {assets.length ? <div className="prod-table-wrap"><table className="prod-table"><thead><tr><th>Identificador</th><th>Equipo / categoría</th><th>Estado físico</th><th>Reservas guardadas</th><th>Editar</th></tr></thead><tbody>{assets.map(asset => <tr key={asset.id}><td>{asset.identifier}</td><td><b>{asset.name}</b><br />{asset.category}{asset.notes && <p>{asset.notes}</p>}</td><td>{asset.status === 'maintenance' ? 'En mantenimiento' : 'Operativo'}</td><td>{contexts.filter(context => context.plan.equipment.some(item => item.assetId === asset.id)).map(context => <p key={context.event.id}>{context.event.agasajado || context.event.cliente} · {context.event.fecha_evento} · {context.event.lugar}</p>)}</td><td><button type="button" disabled={!onUpdateAsset || assetBusy} onClick={() => setEditingAsset({ ...asset })}>Editar ficha</button></td></tr>)}</tbody></table></div> : <p className="prod-empty">Todavía no hay equipos registrados. Puedes crear la primera ficha al final de este apartado.</p>}
        {editingAsset && <section className="prod-resource-card" aria-label="Editar ficha de equipo"><h3>{editingAsset.identifier}</h3><div className="prod-grid"><Field label="Nombre del equipo registrado"><input value={editingAsset.name} onChange={e => setEditingAsset({ ...editingAsset, name: e.target.value })} /></Field><Field label="Identificador del inventario"><input value={editingAsset.identifier} onChange={e => setEditingAsset({ ...editingAsset, identifier: e.target.value })} /></Field><Field label="Categoría del inventario"><input value={editingAsset.category} onChange={e => setEditingAsset({ ...editingAsset, category: e.target.value })} /></Field><Field label="Estado físico del inventario"><select value={editingAsset.status} onChange={e => setEditingAsset({ ...editingAsset, status: e.target.value as EquipmentAsset['status'] })}><option value="available">Operativo</option><option value="maintenance">En mantenimiento</option></select></Field><Field label="Notas de inventario"><textarea value={editingAsset.notes || ''} onChange={e => setEditingAsset({ ...editingAsset, notes: e.target.value })} /></Field></div><div className="prod-actions"><button type="button" disabled={assetBusy || !onUpdateAsset || !editingAsset.name.trim() || !editingAsset.identifier.trim() || !editingAsset.category.trim()} onClick={async () => { if (!onUpdateAsset) return; setAssetBusy(true); try { const { id: assetId, ...patch } = editingAsset; await onUpdateAsset(assetId, patch); setEditingAsset(null); setLocalMessage('Ficha del inventario guardada en Supabase.') } catch (error) { setLocalMessage(error instanceof Error ? error.message : 'No se pudo actualizar el inventario.') } finally { setAssetBusy(false) } }}>{assetBusy ? 'Guardando ficha…' : 'Guardar ficha en inventario'}</button><button type="button" disabled={assetBusy} onClick={() => setEditingAsset(null)}>Cancelar edición de ficha</button></div><p className="prod-muted">Guardar esta ficha actualiza el inventario general de inmediato. Las asignaciones de este evento se guardan con Guardar producción.</p></section>}
        <h3>Asignaciones de este evento</h3>
        <div className="prod-actions"><Field label="Equipo identificado"><select value={selectedAsset} onChange={e => setSelectedAsset(e.target.value)}><option value="">Selecciona un equipo</option>{assets.map(asset => <option key={asset.id} value={asset.id}>{asset.identifier} · {asset.name}{asset.status === 'maintenance' ? ' · EN MANTENIMIENTO' : ''}</option>)}</select></Field><button type="button" disabled={!selectedAsset} onClick={() => { set('equipment', [...plan.equipment, { id: id(), assetId: selectedAsset, start: '', end: '', status: 'reserved', notes: '', transferMinutes: 0 }]); setSelectedAsset('') }}>Asignar equipo</button></div>
        <p className="prod-note">La reserva del equipo debe cubrir instalación, uso, desmontaje y recojo. Registra el margen de traslado hasta el siguiente montaje, incluso cuando haya fechas distintas.</p>
        <div className="prod-resource-list">{plan.equipment.map(assignment => {
          const asset = assets.find(item => item.id === assignment.assetId)
          const update = (patch: Partial<typeof assignment>) => set('equipment', replaceRow(plan.equipment, assignment.id, patch))
          return <article className="prod-resource-card" key={assignment.id}><div className="prod-row-heading"><h3>{asset?.identifier || 'Equipo desconocido'} · {asset?.name}</h3><button type="button" className="prod-danger" onClick={() => set('equipment', plan.equipment.filter(item => item.id !== assignment.id))}>Quitar asignación</button></div>{asset?.status === 'maintenance' && <p className="prod-warning">El equipo está en mantenimiento en el inventario.</p>}<div className="prod-grid"><Field label="Inicio de reserva / montaje (Lima)"><input type="datetime-local" value={assignment.start} onChange={e => update({ start: e.target.value })} /></Field><Field label="Fin de reserva / recojo (Lima)"><input type="datetime-local" value={assignment.end} onChange={e => update({ end: e.target.value })} /></Field><Field label="Estado operativo"><select value={assignment.status} onChange={e => update({ status: e.target.value as typeof assignment.status })}>{Object.entries(equipmentStatus).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></Field><Field label="Traslado para el siguiente montaje (minutos)"><input type="number" min="0" value={assignment.transferMinutes} onChange={e => update({ transferMinutes: Math.max(0, Number(e.target.value)) })} /></Field><Field label="Dimensiones, módulos y observaciones"><textarea value={assignment.notes} onChange={e => update({ notes: e.target.value })} placeholder="Módulos, controladores, fuentes, accesorios y cualquier condición del equipo." /></Field></div></article>
        })}</div>
        {!plan.equipment.length && <p className="prod-empty">Sin equipos asignados.</p>}
        <details className="prod-note"><summary>Registrar un equipo identificable en el inventario</summary><div className="prod-grid"><Field label="Nombre de equipo"><input value={assetName} onChange={e => setAssetName(e.target.value)} placeholder="Pista LED 3 × 2 metros" /></Field><Field label="Identificador único"><input value={assetIdentifier} onChange={e => setAssetIdentifier(e.target.value)} placeholder="PISTA LED 01" /></Field><Field label="Categoría"><select value={assetCategory} onChange={e => setAssetCategory(e.target.value)}>{['Sonido', 'Iluminación', 'Audiovisuales', 'Pistas LED', 'Decoración y animación', 'Otros'].map(name => <option key={name}>{name}</option>)}</select></Field></div><button type="button" disabled={assetBusy || !assetName.trim() || !assetIdentifier.trim()} onClick={async () => { setAssetBusy(true); setLocalMessage(''); try { await onCreateAsset({ name: assetName.trim(), identifier: assetIdentifier.trim(), category: assetCategory, status: 'available', notes: '' }); setAssetName(''); setAssetIdentifier(''); setLocalMessage('Equipo registrado en el inventario. Ya puedes seleccionarlo y asignarlo al evento.') } catch (error) { setLocalMessage(error instanceof Error ? error.message : 'No se pudo registrar el equipo.') } finally { setAssetBusy(false) } }}>{assetBusy ? 'Registrando…' : 'Registrar equipo en Supabase'}</button></details>
      </>}

      {section === 5 && <>
        <div className="prod-grid">{([['departure', 'Salida del almacén'], ['installation', 'Instalación acordada'], ['arrival', 'Llegada al local'], ['test', 'Prueba técnica'], ['serviceStart', 'Inicio de servicio planificado'], ['teardown', 'Inicio de desmontaje'], ['pickup', 'Recojo']] as const).map(([key, label]) => <Field key={key} label={`${label} (Lima)`}><input type="datetime-local" value={plan.logistics[key]} onChange={e => logistics(key, e.target.value)} /></Field>)}<Field label="Montaje estimado (minutos)"><input type="number" min="0" value={plan.logistics.setupMinutes} onChange={e => logistics('setupMinutes', Math.max(0, Number(e.target.value)))} /></Field><Field label="Traslado logístico estimado (minutos)"><input type="number" min="0" value={plan.logistics.transferMinutes} onChange={e => logistics('transferMinutes', Math.max(0, Number(e.target.value)))} /></Field><Field label="Vehículo / placa"><input value={plan.logistics.vehicle} onChange={e => logistics('vehicle', e.target.value)} /></Field><Field label="Destino posterior de los equipos"><input value={plan.logistics.destination} onChange={e => logistics('destination', e.target.value)} /></Field></div>
        <People label="Responsables de instalación" people={assignedPeople} selected={plan.logistics.installerIds} onChange={value => logistics('installerIds', value)} /><People label="Responsables de desmontaje" people={assignedPeople} selected={plan.logistics.teardownIds} onChange={value => logistics('teardownIds', value)} />
        <h3>Condiciones de acceso y operación</h3><div className="prod-grid">{([['floor', 'Piso del evento'], ['elevator', 'Ascensor / capacidad'], ['stairs', 'Escaleras'], ['vehicleAccess', 'Acceso vehicular'], ['parking', 'Estacionamiento'], ['unloading', 'Lugar de descarga'], ['entryRestrictions', 'Restricciones de ingreso'], ['receptionContact', 'Contacto de recepción'], ['electricity', 'Condiciones eléctricas'], ['space', 'Espacio disponible'], ['naturalLight', 'Exposición a luz natural']] as const).map(([key, label]) => <Field key={key} label={label}><input value={plan.logistics[key]} onChange={e => logistics(key, e.target.value)} /></Field>)}</div><Field label="Observaciones logísticas internas"><textarea rows={4} value={plan.logistics.notes} onChange={e => logistics('notes', e.target.value)} /></Field><p className="prod-note">Las fechas completas permiten montar el día anterior y recoger al día siguiente. Si cambia un horario acordado con el cliente, registra también el acuerdo en Contrato y servicios.</p>
      </>}

      {section === 6 && <>
        <p className="prod-note">Salida y retorno tienen marcas independientes. Registrar la salida no confirma que el material haya regresado.</p>
        <div className="prod-advanced-checklists">{([{ title: 'Salida del almacén', tasks: departure, isReturn: false }, { title: 'Retorno y revisión', tasks: returns, isReturn: true }]).map(group => <section key={group.title} className="prod-check-stage"><h3>{group.title} · {group.tasks.filter(task => task.done).length}/{group.tasks.length}</h3>{group.tasks.map(item => <label className="prod-check" key={item.id}><input type="checkbox" checked={item.done} onChange={e => { const base = group.isReturn ? mergeReturnChecklist(event, plan) : plan; onChange({ ...base, checklist: [...base.checklist.filter(task => task.id !== item.id), { ...item, done: e.target.checked, completedBy: e.target.checked ? userId : undefined, completedAt: e.target.checked ? new Date().toISOString() : undefined }] }) }} /><span>{item.label}{item.done && <small>{productionDate(item.completedAt || '')} · {item.completedBy || 'Sin autor'}</small>}</span></label>)}</section>)}</div>
        <details className="prod-note"><summary>Otras tareas guardadas del plan</summary>{(Object.keys(stageNames) as (keyof typeof stageNames)[]).map(stage => <section key={stage} className="prod-check-stage"><h3>{stageNames[stage]}</h3>{plan.checklist.filter(item => item.stage === stage && !departure.some(task => task.id === item.id) && !returns.some(task => task.id === item.id)).map(item => <label className="prod-check" key={item.id}><input type="checkbox" checked={item.done} onChange={e => set('checklist', replaceRow(plan.checklist, item.id, { done: e.target.checked, completedBy: e.target.checked ? userId : undefined, completedAt: e.target.checked ? new Date().toISOString() : undefined }))} /><span>{item.label}{item.done && <small>Completado {productionDate(item.completedAt || '')} · usuario {item.completedBy || 'No registrado'}</small>}</span></label>)}</section>)}</details>
        <div className="prod-actions"><Field label="Nueva tarea de producción"><input value={newTask} onChange={e => setNewTask(e.target.value)} /></Field><Field label="Etapa de la tarea"><select value={newTaskStage} onChange={e => setNewTaskStage(e.target.value as typeof newTaskStage)}>{Object.entries(stageNames).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></Field><button type="button" disabled={!newTask.trim()} onClick={() => { set('checklist', [...plan.checklist, { id: id(), label: newTask.trim(), stage: newTaskStage, done: false }]); setNewTask('') }}>Añadir tarea</button></div>
      </>}

      {section === 7 && <>
        <p className="prod-note">Información interna de administración. El importe contractual y el adelanto provienen del CRM. Los pagos que añadas aquí deben ser posteriores y adicionales al adelanto, para evitar contarlos dos veces.</p>
        <div className="prod-metrics"><div className="prod-metric"><span>Ingreso contratado</span><strong>{amount(event.total)}</strong></div><div className="prod-metric"><span>Adelanto del CRM</span><strong>{amount(event.adelanto)}</strong></div><div className="prod-metric"><span>Pagos adicionales</span><strong>{amount(additionalPayments)}</strong></div><div className="prod-metric"><span>Saldo calculado</span><strong>{amount(balance(event, plan))}</strong></div></div>
        <p className="prod-muted">Se calcula total − adelanto − pagos adicionales registrados. El campo «saldo» guardado en el CRM no se utiliza. No existe un registro separado de descuentos en el esquema actual; cualquier descuento comercial debe verificarse en el contrato.</p>
        <h3>Pagos adicionales al adelanto</h3>{plan.payments.map(payment => <article className="prod-resource-card" key={payment.id}><div className="prod-grid"><Field label="Importe del pago adicional (S/)"><input type="number" min="0" step="0.01" value={payment.amount} onChange={e => set('payments', replaceRow(plan.payments, payment.id, { amount: Math.max(0, Number(e.target.value)) }))} /></Field><Field label="Fecha del pago adicional (Lima)"><input type="datetime-local" value={payment.date} onChange={e => set('payments', replaceRow(plan.payments, payment.id, { date: e.target.value }))} /></Field><Field label="Referencia / comprobante del pago"><input value={payment.note} onChange={e => set('payments', replaceRow(plan.payments, payment.id, { note: e.target.value }))} /></Field></div><button type="button" className="prod-danger" onClick={() => set('payments', plan.payments.filter(item => item.id !== payment.id))}>Quitar pago del borrador</button></article>)}<button type="button" onClick={() => set('payments', [...plan.payments, { id: id(), amount: 0, date: '', note: '' }])}>Añadir pago adicional</button>
        <h3>Costos internos de producción</h3><p>Honorarios registrados en Personal: <b>{amount(staffingCosts)}</b>. Ya se incluyen en el costo operativo y no debes volver a agregarlos aquí.</p>
        {plan.costs.map(cost => <article className="prod-resource-card" key={cost.id}><div className="prod-grid"><Field label="Categoría del costo"><input list="production-costs" value={cost.category} onChange={e => set('costs', replaceRow(plan.costs, cost.id, { category: e.target.value }))} /></Field><Field label="Descripción del costo"><input value={cost.description} onChange={e => set('costs', replaceRow(plan.costs, cost.id, { description: e.target.value }))} /></Field><Field label="Costo (S/)"><input type="number" min="0" step="0.01" value={cost.amount} onChange={e => set('costs', replaceRow(plan.costs, cost.id, { amount: Math.max(0, Number(e.target.value)) }))} /></Field></div><button type="button" className="prod-danger" onClick={() => set('costs', plan.costs.filter(item => item.id !== cost.id))}>Quitar costo</button></article>)}<button type="button" onClick={() => set('costs', [...plan.costs, { id: id(), category: '', description: '', amount: 0 }])}>Añadir costo interno</button><datalist id="production-costs">{['DJ', 'Animación', 'Glitter', 'Personal de montaje', 'Movilidad', 'Alquiler de equipos', 'Otros gastos'].map(value => <option key={value} value={value} />)}</datalist><div className="prod-metrics"><div className="prod-metric"><span>Costos operativos + honorarios</span><strong>{amount(operatingCosts)}</strong></div><div className="prod-metric"><span>Utilidad estimada</span><strong>{amount(operationalUtility(event, plan))}</strong></div></div>
      </>}

      {section === 8 && <>
        <h3>Registrar una incidencia o novedad interna</h3><div className="prod-grid"><Field label="Tipo de novedad"><select value={incidentKind} onChange={e => setIncidentKind(e.target.value)}>{['Incidencia', 'Coordinación interna', 'Cambio logístico', 'Seguimiento de montaje', 'Seguimiento del show'].map(label => <option key={label}>{label}</option>)}</select></Field><Field label="Descripción de la novedad"><textarea value={incident} onChange={e => setIncident(e.target.value)} /></Field></div><button type="button" disabled={!incident.trim()} onClick={() => { const entry = `[${incidentKind} · ${productionDate(new Date().toISOString())} · usuario ${userId}]\n${incident.trim()}`; set('notes', [plan.notes, entry].filter(Boolean).join('\n\n')); setIncident(''); setLocalMessage('Novedad añadida al borrador interno. Guarda la producción para registrarla en Supabase y en la bitácora.') }}>Añadir novedad al borrador</button><Field label="Comentarios internos de producción"><textarea rows={5} value={plan.notes} onChange={e => set('notes', e.target.value)} /></Field><h3>Acuerdos confirmados con el cliente</h3>{plan.agreements.length ? plan.agreements.map(item => <article className="prod-resource-card" key={item.id}><b>{productionDate(item.date)} · {item.responsible}</b><p className="prod-preserve">{item.note}</p></article>) : <p className="prod-empty">Sin acuerdos adicionales registrados. Usa Contrato y servicios para añadirlos.</p>}<h3>Historial de cambios guardados</h3><p className="prod-muted">El historial lo registra Supabase con el usuario autenticado y los valores anteriores y nuevos. Los cambios del borrador aparecerán después de guardarse.</p>{journal.length ? <div className="prod-journal">{journal.map(entry => <article key={entry.id}><b>{productionDate(entry.created_at)} · {entry.action}</b><p>Usuario: {entry.actor}</p><p>{entry.description}</p><details><summary>Consultar valores anteriores y nuevos</summary><h4>Anterior</h4><pre>{JSON.stringify(entry.old_value, null, 2) || 'Sin versión anterior'}</pre><h4>Nuevo</h4><pre>{JSON.stringify(entry.new_value, null, 2) || 'Sin valor nuevo'}</pre></details></article>)}</div> : <p className="prod-empty">Todavía no hay cambios guardados en la bitácora.</p>}
      </>}
      {section === 9 && <>
        <p className="prod-note">Configura actividades reutilizables para este plan. Los minutos se cuentan respecto del inicio del evento: −60 equivale a una hora antes. Aplicar plantillas añade propuestas pendientes; conserva las actividades y confirmaciones existentes.</p>
        <div className="prod-actions"><button type="button" onClick={() => set('activityTemplates', [...templates, { id: id(), name: '', kind: 'other' }])}>Nueva plantilla</button><button type="button" disabled={!templates.length || templates.some(template => templateProblems(template).length > 0)} onClick={() => { const result = applyActivityTemplates(event, plan, templates); onChange(result.plan); setLocalMessage(`Plantillas aplicadas al borrador: ${result.added} actividades nuevas y ${result.preserved} existentes conservadas. Guarda producción para persistirlas.\n${result.warnings.join('\n')}`) }}>Añadir propuestas al cronograma</button><button type="button" disabled={!templates.length} onClick={() => { const url = URL.createObjectURL(new Blob([JSON.stringify(templates, null, 2)], { type: 'application/json' })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'MRF_plantillas_produccion.json'; anchor.click(); window.setTimeout(() => URL.revokeObjectURL(url), 10000) }}>Exportar configuración</button><label className="prod-advanced-import">Importar configuración<input type="file" accept="application/json,.json" onChange={async e => { const file = e.target.files?.[0]; e.target.value = ''; if (!file) return; try { if (file.size > 262144) throw new Error('El archivo de plantillas supera 256 KB.'); const imported = parseActivityTemplates(await file.text()); set('activityTemplates', imported); setLocalMessage(`Se importaron ${imported.length} plantillas al borrador. Las actividades existentes se conservaron. Guarda producción para conservar esta configuración.`) } catch (error) { setLocalMessage(error instanceof Error ? error.message : 'No se pudo importar la configuración.') } }} /></label></div>
        {!templates.length && <p className="prod-empty">Todavía no hay plantillas configuradas. Puedes crearlas o importar una configuración previamente exportada.</p>}
        {templates.map(template => <article className="prod-resource-card" key={template.id}><div className="prod-row-heading"><h3>{template.name || 'Nueva plantilla'}</h3><button type="button" className="prod-danger" onClick={() => set('activityTemplates', templates.filter(item => item.id !== template.id))}>Quitar plantilla</button></div><div className="prod-grid"><Field label="Nombre de la plantilla"><input value={template.name} onChange={e => updateTemplate(template, { name: e.target.value })} /></Field><Field label="Tipo de la plantilla"><select value={template.kind} onChange={e => updateTemplate(template, { kind: e.target.value as ActivityTemplate['kind'] })}>{Object.entries(activityKind).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></Field><Field label="Minutos respecto al inicio del evento"><input type="number" min="-10080" max="10080" step="1" value={template.offsetMinutes ?? ''} placeholder="Sin horario propuesto" onChange={e => updateTemplate(template, { offsetMinutes: e.target.value === '' ? undefined : Number(e.target.value) })} /></Field><Field label="Duración propuesta (minutos)"><input type="number" min="1" max="10080" step="1" value={template.durationMinutes ?? ''} placeholder="Por definir" onChange={e => updateTemplate(template, { durationMinutes: e.target.value === '' ? undefined : Number(e.target.value) })} /></Field><Field label="Aplicar solo si el servicio está contratado"><select value={template.serviceKey || ''} onChange={e => updateTemplate(template, { serviceKey: e.target.value || undefined })}><option value="">Cualquier evento</option>{services.map(service => <option key={service.key} value={service.key}>{service.label}</option>)}</select></Field></div>{templateProblems(template).map(problem => <p className="prod-warning" key={problem}>{problem}</p>)}</article>)}
      </>}
    </section>
  </div>
}

function Timeline({ activities }: { activities: Activity[] }) {
  const points = activities.filter(activity => activity.start && activity.end && activity.status !== 'cancelled').map(activity => ({ activity, start: Date.parse(`${activity.start}-05:00`), end: Date.parse(`${activity.end}-05:00`) })).filter(item => Number.isFinite(item.start) && Number.isFinite(item.end) && item.end > item.start)
  if (!points.length) return null
  const min = Math.min(...points.map(item => item.start)); const max = Math.max(...points.map(item => item.end)); const span = max - min || 1
  return <div className="prod-timeline" aria-label="Línea de tiempo del evento"><div className="prod-timeline-axis"><span>{productionDate(new Date(min).toISOString())}</span><span>{productionDate(new Date(max).toISOString())}</span></div>{points.sort((a, b) => a.start - b.start).map(({ activity, start, end }) => <div className="prod-timeline-row" key={activity.id}><span>{activity.name}<small>{productionDate(activity.start)} – {productionDate(activity.end)}</small></span><div className="prod-timeline-track"><div className={`prod-timeline-bar ${activity.kind}`} style={{ marginLeft: `${(start - min) / span * 100}%`, width: `${Math.max(0.4, (end - start) / span * 100)}%` }} title={`${activity.name}: ${productionDate(activity.start)} – ${productionDate(activity.end)}`} /></div></div>)}</div>
}
